package auth
import("context";"testing";"time";"github.com/11DingKing/vocational-admission-go/internal/domain";"github.com/11DingKing/vocational-admission-go/internal/repository";"github.com/11DingKing/vocational-admission-go/internal/storage")
func TestExpiredSessionIsForbidden(t *testing.T){db,e:=storage.Open(context.Background(),"file:expiry?mode=memory&cache=shared");if e!=nil{t.Fatal(e)};defer db.Close();if e=storage.Migrate(context.Background(),db.SQL);e!=nil{t.Fatal(e)};if _,e=db.SQL.Exec("INSERT INTO users(username,password_hash,role,created_at) VALUES('u','x','officer',datetime('now'))");e!=nil{t.Fatal(e)};now:=time.Now().UTC();if e=(repository.SessionRepo{DB:db.SQL}).Create(context.Background(),domain.Session{ID:"expired",UserID:1,CreatedAt:now.Add(-time.Hour),ExpiresAt:now.Add(-time.Minute)});e!=nil{t.Fatal(e)};s:=Service{Users:repository.UserRepo{DB:db.SQL},Sessions:repository.SessionRepo{DB:db.SQL}};if _,e=s.Authenticate(context.Background(),"expired");e==nil{t.Fatal("expired session authenticated")}}
